import itertools

def is_valid_string(s):
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def match_parens(lst):
    if len(lst) != 2 or not all(isinstance(s, str) for s in lst):
        return 'No'

    for perm in itertools.permutations(lst):
        new_str = ''.join(perm)
        if is_valid_string(new_str):
            return 'Yes'

    return 'No'

